// Firebase services - will be replaced with actual Firebase when configured
// For now, using mock implementations to allow build to succeed

// Mock Firebase initialization
const initializeFirebase = () => {
  console.log('📱 Using mock Firebase for development');
};

// Mock service classes
class AuthService {
  signIn() { return Promise.resolve({ user: { id: 'mock_user' } }); }
  signUp() { return Promise.resolve({ user: { id: 'mock_user' } }); }
  signOut() { return Promise.resolve(); }
}

class FirestoreService {
  add() { return Promise.resolve({ id: 'mock_doc_id' }); }
  get() { return Promise.resolve(null); }
  update() { return Promise.resolve(); }
  delete() { return Promise.resolve(); }
}

class StorageService {
  upload() { return Promise.resolve({ url: 'https://placeholder.com/image.jpg' }); }
  delete() { return Promise.resolve(); }
}

// Initialize Firebase and services
let firebaseServices = null;

export const initializeFirebaseServices = () => {
  if (!firebaseServices) {
    try {
      initializeFirebase();

      firebaseServices = {
        auth: new AuthService(),
        firestore: new FirestoreService(),
        storage: new StorageService()
      };

      console.log('Firebase services initialized successfully');
    } catch (error) {
      console.error('Failed to initialize Firebase services:', error);
      throw error;
    }
  }

  return firebaseServices;
};

export const getFirebaseServices = () => {
  if (!firebaseServices) {
    throw new Error('Firebase services not initialized. Call initializeFirebaseServices() first.');
  }
  return firebaseServices;
};

// Convenience exports
export const getAuthService = () => getFirebaseServices().auth;
export const getFirestoreService = () => getFirebaseServices().firestore;
export const getStorageService = () => getFirebaseServices().storage;
